#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n,m;scanf("%d %d",&n,&m);
vector<vector<int>>g(n+1);vector<int>indeg(n+1,0);
for(int i=0;i<m;++i){int u,v;scanf("%d %d",&u,&v);
g[v].push_back(u);++indeg[u];}
queue<int>q;for(int i=1;i<=n;++i)if(indeg[i]==0)q.push(i);
vector<bool>safe(n+1,false);
while(!q.empty()){int u=q.front();q.pop();safe[u]=true;
for(int v:g[u])if(--indeg[v]==0)q.push(v);}
bool first=true;
for(int i=1;i<=n;++i)if(safe[i]){if(!first)printf(" ");printf("%d",i);first=false;}
printf("\n");return 0;}

